class Solution:
    def distinctPoints(self, s: str, k: int) -> int:
        mv = {'U': (0, 1), 'D': (0, -1), 'L': (-1, 0), 'R': (1, 0)}
        seen = set()
        n = len(s)
        for i in range(n - k + 1):
            x = y = 0
            for j, ch in enumerate(s):
                if i <= j < i + k:
                    continue
                dx, dy = mv[ch]
                x += dx; y += dy
            seen.add((x, y))
        return len(seen)

