class Solution {
public:
    int distinctPoints(string s, int k) {
        int n = s.size();
        set<pair<long long,long long>> seen;
        for (int i = 0; i + k <= n; i++) {
            long long x = 0, y = 0;
            for (int j = 0; j < n; j++) {
                if (j >= i && j < i + k) continue;
                if (s[j]=='U') y++; else if (s[j]=='D') y--;
                else if (s[j]=='L') x--; else x++;
            }
            seen.insert({x, y});
        }
        return seen.size();
    }
};

