class Solution {
public:
    int distinctPoints(string s, int k) {
        int n = s.size();
        vector<long long> px(n+1,0), py(n+1,0);
        for (int i = 0; i < n; i++) {
            long long dx = 0, dy = 0;
            if (s[i]=='U') dy = 1; else if (s[i]=='D') dy = -1;
            else if (s[i]=='L') dx = -1; else dx = 1;
            px[i+1] = px[i] + dx; py[i+1] = py[i] + dy;
        }
        set<pair<long long,long long>> seen;
        for (int i = 0; i + k <= n; i++)
            seen.insert({px[n] - (px[i+k]-px[i]), py[n] - (py[i+k]-py[i])});
        return seen.size();
    }
};

