class Solution {
    public int distinctPoints(String s, int k) {
        int n = s.length();
        long[] px = new long[n+1], py = new long[n+1];
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            long dx = c=='L' ? -1 : c=='R' ? 1 : 0;
            long dy = c=='U' ? 1 : c=='D' ? -1 : 0;
            px[i+1] = px[i] + dx; py[i+1] = py[i] + dy;
        }
        Set<Long> seen = new HashSet<>();
        for (int i = 0; i + k <= n; i++) {
            long x = px[n] - (px[i+k] - px[i]);
            long y = py[n] - (py[i+k] - py[i]);
            seen.add((x + 100000L) * 200003L + (y + 100000L));
        }
        return seen.size();
    }
}

